import random
import string
from typing import List

# Generator for libnuma nodes list/range strings (ASCII, NUL-terminated when passed via c_str()).
# We aim to produce valid, interesting inputs covering:
# - single ids, ranges, mixed lists
# - large node indices, zero and max boundaries
# - overlapping/adjacent ranges, duplicates
# - open variety of ordering (ascending/descending in text, though ranges are start-end with start<=end)
# - inclusion of potential whitespace variants (kept minimal to remain broadly valid)
# - different delimiters counts and lengths
# Output limited to <= 4096 bytes

MAX_OUTPUT_BYTES = 4096

# Heuristics for node universe size; many environments default to 128 nodes; some to 2048.
DEFAULT_POSSIBLE_NODES_CHOICES = [8, 16, 32, 64, 96, 128, 256, 512, 1024, 2048]


def _pick_universe(rng: random.Random) -> int:
    # Bias toward common sizes but allow larger
    if rng.random() < 0.7:
        return rng.choice(DEFAULT_POSSIBLE_NODES_CHOICES)
    # Occasionally pick arbitrary but reasonable size
    return rng.randint(4, 4096)


def _gen_id(rng: random.Random, max_node: int) -> int:
    # Favor boundary and near-boundary values
    specials = [0, 1, 2, max(0, max_node - 1), max(0, max_node - 2), max_node]
    if rng.random() < 0.6:
        return max(0, rng.choice(specials))
    # General case within [0, max_node]
    return rng.randint(0, max_node)


def _gen_range(rng: random.Random, max_node: int) -> str:
    a = _gen_id(rng, max_node)
    # Ranges should satisfy start <= end
    # Choose length with bias to short ranges
    if rng.random() < 0.75:
        length = rng.randint(0, min(8, max_node))
    else:
        # Occasionally generate longer ranges
        length = rng.randint(0, min(max_node, max(8, max_node // 4)))
    b = min(max_node, a + length)
    return f"{a}-{b}"


def _gen_single_or_range(rng: random.Random, max_node: int) -> str:
    if rng.random() < 0.5:
        return str(_gen_id(rng, max_node))
    return _gen_range(rng, max_node)


def _maybe_ws(rng: random.Random) -> str:
    # Some parsers allow spaces; keep minimal to stay valid across implementations
    if rng.random() < 0.2:
        return ""
    if rng.random() < 0.2:
        return " "
    return ""


def _compose_list(items: List[str], rng: random.Random) -> str:
    # Join with commas; occasionally add spaces around commas
    parts = []
    for i, it in enumerate(items):
        if i > 0:
            # Insert comma and optional surrounding space
            if rng.random() < 0.25:
                parts.append(", ")
            else:
                parts.append(",")
        parts.append(it)
    return "".join(parts)


def _gen_nodestring(rng: random.Random) -> str:
    max_node = _pick_universe(rng) - 1

    # Choose pattern
    pattern = rng.random()
    if pattern < 0.15:
        # Single ID
        s = str(_gen_id(rng, max_node))
    elif pattern < 0.30:
        # Single range
        s = _gen_range(rng, max_node)
    elif pattern < 0.55:
        # Mixed short list
        n = rng.randint(2, 5)
        items = [_gen_single_or_range(rng, max_node) for _ in range(n)]
        s = _compose_list(items, rng)
    elif pattern < 0.80:
        # Larger list with potential duplicates and adjacent ranges
        n = rng.randint(5, 15)
        items = []
        for _ in range(n):
            if rng.random() < 0.6:
                items.append(str(_gen_id(rng, max_node)))
            else:
                items.append(_gen_range(rng, max_node))
        s = _compose_list(items, rng)
    else:
        # Crafted boundary-heavy string
        elems = [
            f"0-{min(3, max_node)}",
            str(max(0, max_node)),
            f"{max(0, max_node-3)}-{max_node}",
            "1",
            "2",
        ]
