    if rng.random() < 0.3:
        left = "" if rng.random() < 0.5 else " "
        right = "" if rng.random() < 0.5 else " "
        s = f"{left}{s}{right}"

    # Ensure size bound; if too long, trim at last comma-safe boundary
    if len(s) > MAX_OUTPUT_BYTES:
        # find last comma before limit
        cut = s.rfind(",", 0, MAX_OUTPUT_BYTES)
        if cut == -1:
            s = s[:MAX_OUTPUT_BYTES]
        else:
            s = s[:cut]

    return s


