# large IDs, zeros, duplicates, overlapping ranges, ascending/descending components (but valid ranges require start<=end),
# and hex-like forms are typically not accepted, so keep decimal.
# Ensure NUL-terminated when consumed by C via std::string.c_str() (the fuzz harness will add NUL).

MAX_OUTPUT_BYTES = 4096

# Reasonable upper bounds for CPU ids observed in practice.
# The fuzz stub queries numa_num_possible_cpus() but our input only affects the parser.
# Use a broad range to exercise big masks but keep strings short.
DEFAULT_MAX_CPU = 1024


def _rand_bool(r: random.Random, p: float) -> bool:
    return r.random() < p


def _pick_cpu_id(r: random.Random, max_cpu: int) -> int:
    # Bias toward small IDs and boundaries
    choices = [0, 1, 2, 3, 7, 15, 31, 63, 127, 255, 511, 1023, max(0, max_cpu - 1)]
    if _rand_bool(r, 0.6):
        return r.choice([c for c in choices if c < max_cpu])
    # Skewed random within range
    base = int(r.betavariate(0.6, 1.5) * max(1, max_cpu - 1))
    return min(base, max_cpu - 1)


