    return str(n)


def _make_range(r: random.Random, max_cpu: int) -> Tuple[int, int]:
    a = _pick_cpu_id(r, max_cpu)
    if _rand_bool(r, 0.5):
        # small span
        span = r.randint(0, min(16, max(0, max_cpu - 1 - a)))
        b = a + span
    else:
        b = _pick_cpu_id(r, max_cpu)
        if b < a:
            a, b = b, a
    return a, b


