    # Some parsers ignore spaces; include occasionally
    if _rand_bool(r, 0.3):
        return r.choice(["", " ", "  "])
    return ""


def _component(r: random.Random, max_cpu: int) -> str:
    kind = r.choices(
        population=["single", "range", "range_with_spaces"],
        weights=[0.45, 0.45, 0.10],
        k=1,
    )[0]

    if kind == "single":
        n = _pick_cpu_id(r, max_cpu)
        return _emit_int(n)
    else:
        a, b = _make_range(r, max_cpu)
        if kind == "range_with_spaces":
            return f"{_emit_int(a)}{_maybe_space(r)}-{_maybe_space(r)}{_emit_int(b)}"
        return f"{_emit_int(a)}-{_emit_int(b)}"


