    # Choose an upper bound for CPU IDs used in the string
    max_cpu = r.choice([64, 128, 256, 512, 1024, DEFAULT_MAX_CPU])

    s = _mix_components(r, max_cpu)

    # Ensure non-empty and valid decimal content
    if not s:
        s = "0"

    out = s.encode("ascii", errors="strict")
    return _cap_size(out)
